function tripletCount(a, b, c) {
  const countParities = (values) => {
    const counts = [0, 0];
    for (const value of values) {
      let rest = value;
      let parity = 0;
      while (rest > 0) {
        rest &= rest - 1;
        parity ^= 1;
      }
      counts[parity]++;
    }
    return counts;
  };
  const countA = countParities(a);
  const countB = countParities(b);
  const countC = countParities(c);

  let total = 0;
  for (const parityA of [0, 1]) {
    for (const parityB of [0, 1]) {
      total += countA[parityA] * countB[parityB] * countC[parityA ^ parityB];
    }
  }
  return total;
}

