function tripletCount(a, b, c) {
  let count = 0;
  for (const x of a)
    for (const y of b)
      for (const z of c) {
        const ones = (x ^ y ^ z).toString(2).split('').filter(bit => bit === '1').length;
        if (ones % 2 === 0) count++;
      }
  return count;
}

