function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const array = () => {
    const length = size === 'large' ? int(1500, 2000) : int(1, 6);
    const top = size === 'large' || rand() < 0.3 ? 1000000000 : 15;
    // Sometimes use only powers of two (one 1 bit each), so whole arrays share an odd parity.
    const powers = rand() < 0.2;
    return Array.from({ length }, () => powers ? 2 ** int(0, top === 15 ? 3 : 29) : int(0, top));
  };
  return [array(), array(), array()];
}
